import limited_client as robot, numpy as np
from PIL import Image
from collections import deque
o=robot.observe(camera=1); Image.fromarray(o['rgb']).save('/app/output/wall_detect1.png')
rgb=o['rgb'].astype(int); d=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world']
print('TCP',o['robot']['tcp_position'],'grip',o['robot']['gripper_positions'],'q',o['robot']['joint_positions'],'status',robot.status())
# dark pixels on wall plane, exclude background beyond wall and robot region
lum=rgb.mean(2); m=(lum<125)&(d>0.2)&(d<1.5)
seen=np.zeros(m.shape,bool); comps=[]
for y,x in zip(*np.where(m)):
 if seen[y,x]: continue
 stack=[(y,x)]; seen[y,x]=1; pts=[]
 while stack:
  a,b=stack.pop(); pts.append((a,b))
  for aa in range(max(0,a-1),min(480,a+2)):
   for bb in range(max(0,b-1),min(480,b+2)):
    if m[aa,bb] and not seen[aa,bb]: seen[aa,bb]=1;stack.append((aa,bb))
 if 2<=len(pts)<=500:
  ys=[p[0] for p in pts]; xs=[p[1] for p in pts]; comps.append((len(pts),np.mean(xs),np.mean(ys),(min(xs),max(xs),min(ys),max(ys))))
print('components',sorted(comps,key=lambda x:-x[0])[:25])
def wp(u,v):
 z=float(d[v,u]); pc=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);return z,(T@pc)[:3].round(4).tolist(),rgb[v,u].tolist()
for u,v in [(92,135),(117,176),(225,142),(230,142),(235,142),(220,145),(250,150)]:print((u,v),wp(u,v))
